def transpose_records(records):
    if not records:
        return []

    order = []
    seen = set()
    for rec in records:
        for key in rec:
            if key not in seen:
                seen.add(key)
                order.append(key)

    if not order:
        return []

    result = []
    for key in order:
        col = [rec.get(key) for rec in records]
        result.append([key, col])

    return result
